 const calls=[...texts.map((text,i)=>({text,i,period:'current'})),...past.map((text,i)=>({text,i,period:'previous'}))].map(({text,i,period})=>({id:digest([name,period,i]).slice(0,24),factId,channelId:period==='current'?name+'-'+i:name+'-past-'+i,period,runId:'run-'+name+'-'+period+i,operator:'operator-'+i,topics,transcript:text,complete:true,instruction:def.instruction,businessContext:context,assessment:{status:'assessed',value:type==='strength'||period==='previous',normalized:type==='strength'||period==='previous'?1:0,rationale:metric==='introduction'?'Оператор не назвал имя.':metric==='upsell'?'Предложение не зафиксировано.':type==='strength'||period==='previous'?'Сохранена положительная оценка критерия.':'Сохранена отрицательная оценка критерия.',quote:''}}));
 return{name,activity,candidates:[fact],calls,allowed,input:actionableInsightsInput([fact],calls,{name:projectName,description:projectDescription,systemPrompt:context,customMetricsSchema:[{id:metric,description:def.instruction}]})};
